CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  notes TEXT,
  category_id TEXT REFERENCES categories(id) ON DELETE SET NULL,
  priority TEXT NOT NULL DEFAULT 'medium',
  energy TEXT,
  date TEXT NOT NULL,
  start_time TEXT,
  duration_min INTEGER,
  is_fixed INTEGER NOT NULL DEFAULT 0,
  is_top3 INTEGER NOT NULL DEFAULT 0,
  goal_id TEXT REFERENCES goals(id) ON DELETE SET NULL,
  habit_id TEXT REFERENCES habits(id) ON DELETE SET NULL,
  source TEXT NOT NULL DEFAULT 'manual',
  routine_task_id TEXT REFERENCES routine_tasks(id),
  status TEXT NOT NULL DEFAULT 'planned',
  skip_reason TEXT,
  timer_mode TEXT,
  reminder_lead_min INTEGER,
  parent_task_id TEXT REFERENCES tasks(id),
  moved_to_task_id TEXT REFERENCES tasks(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (priority IN ('low', 'medium', 'high')),
  CHECK (energy IS NULL OR energy IN ('low', 'medium', 'high')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (start_time IS NULL OR start_time GLOB '[0-2][0-9]:[0-5][0-9]'),
  CHECK (duration_min IS NULL OR duration_min > 0),
  CHECK (is_fixed IN (0, 1)),
  CHECK (is_top3 IN (0, 1)),
  CHECK (source IN ('manual', 'routine', 'shifted', 'import', 'inbox')),
  CHECK (status IN ('planned', 'in_progress', 'done', 'skipped', 'moved', 'missed')),
  CHECK (timer_mode IS NULL OR timer_mode IN ('free', 'countdown', 'sprint', 'tiny_start')),
  CHECK (reminder_lead_min IS NULL OR reminder_lead_min >= 0),
