CREATE TABLE IF NOT EXISTS day_plans (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  day_type TEXT NOT NULL DEFAULT 'normal',
  day_order_index INTEGER,
  timetable_id TEXT REFERENCES timetables(id) ON DELETE SET NULL,
  is_locked INTEGER NOT NULL DEFAULT 0,
  locked_at TEXT,
  sealed_at TEXT,
  intention TEXT,
  mood INTEGER,
  energy_morning TEXT,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (day_type IN ('normal', 'holiday', 'exam', 'rest', 'day_order')),
  CHECK (day_order_index IS NULL OR day_order_index >= 1),
  CHECK (is_locked IN (0, 1)),
  CHECK (mood IS NULL OR mood BETWEEN 1 AND 5),
  CHECK (energy_morning IS NULL OR energy_morning IN ('low', 'okay', 'high')),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS shift_batches (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  scope TEXT NOT NULL,
  from_date TEXT NOT NULL,
  to_date TEXT,
  snapshot_json TEXT NOT NULL,
  moved_count INTEGER NOT NULL DEFAULT 0,
  skipped_count INTEGER NOT NULL DEFAULT 0,
  overflow_count INTEGER NOT NULL DEFAULT 0,
  fixed_protected_count INTEGER NOT NULL DEFAULT 0,
  undone_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (kind IN ('push_forward', 'pull_back', 'swap_days', 'set_day_order', 'mark_holiday', 'shift_times', 'compress', 'move_skip', 'reset_day', 'distribute', 'stack')),
  CHECK (scope IN ('today', 'week', 'until_date', 'routine_end')),
  CHECK (from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date),
  CHECK (json_valid(snapshot_json)),
  CHECK (moved_count >= 0),
  CHECK (skipped_count >= 0),
  CHECK (overflow_count >= 0),
  CHECK (fixed_protected_count >= 0)
);

CREATE TABLE IF NOT EXISTS overrides (
  id TEXT PRIMARY KEY NOT NULL,
