  action TEXT NOT NULL,
  payload_json TEXT,
  reason TEXT,
  batch_id TEXT REFERENCES shift_batches(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (action IN ('skip', 'move', 'edit')),
  CHECK (payload_json IS NULL OR json_valid(payload_json)),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS timetables (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  cycle_type TEXT NOT NULL,
  cycle_length INTEGER NOT NULL,
  attendance_limit_pct INTEGER NOT NULL DEFAULT 75,
  version INTEGER NOT NULL DEFAULT 1,
  source_share_id TEXT REFERENCES timetable_shares(id) ON DELETE SET NULL,
  source_version INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (cycle_type IN ('weekly', 'day_order')),
  CHECK (cycle_length BETWEEN 2 AND 10),
  CHECK (attendance_limit_pct BETWEEN 0 AND 100),
  CHECK (version >= 1),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS timetable_shares (
  id TEXT PRIMARY KEY NOT NULL,
