  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (kind IN ('holiday', 'exam', 'event')),
  CHECK (source IN ('manual', 'ics', 'holiday_calendar')),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS holiday_calendars (
  id TEXT PRIMARY KEY NOT NULL,
  country TEXT NOT NULL,
  region TEXT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE IF NOT EXISTS holiday_dates (
  id TEXT PRIMARY KEY NOT NULL,
  holiday_calendar_id TEXT NOT NULL REFERENCES holiday_calendars(id),
  date TEXT NOT NULL,
  title TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')
);

CREATE TABLE IF NOT EXISTS user_holiday_calendars (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  holiday_calendar_id TEXT NOT NULL REFERENCES holiday_calendars(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS ics_feeds (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  direction TEXT NOT NULL,
  url TEXT,
  token_hash TEXT UNIQUE,
  last_synced_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (direction IN ('import', 'export')),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS focus_sessions (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  started_at TEXT NOT NULL,
  ended_at TEXT,
  planned_min INTEGER,
  actual_min INTEGER,
  mode TEXT NOT NULL,
  work_min INTEGER,
  break_min INTEGER,
  round_no INTEGER,
  interruptions INTEGER NOT NULL DEFAULT 0,
  last_heartbeat_at TEXT,
  duration_confirmed INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at),
  CHECK (planned_min IS NULL OR planned_min > 0),
  CHECK (actual_min IS NULL OR actual_min >= 0),
  CHECK (mode IN ('free', 'countdown', 'sprint', 'tiny_start')),
  CHECK (work_min IS NULL OR work_min > 0),
  CHECK (break_min IS NULL OR break_min > 0),
  CHECK (round_no IS NULL OR round_no >= 1),
  CHECK (interruptions >= 0),
  CHECK (duration_confirmed IN (0, 1)),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS completions (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL REFERENCES tasks(id),
  date TEXT NOT NULL,
  completed_at TEXT NOT NULL,
  actual_min INTEGER,
  on_time INTEGER NOT NULL DEFAULT 1,
  xp INTEGER NOT NULL DEFAULT 0,
  undone_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (actual_min IS NULL OR actual_min >= 0),
  CHECK (on_time IN (0, 1)),
  CHECK (xp >= 0)
);

CREATE TABLE IF NOT EXISTS start_nudges (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id) ON DELETE CASCADE,
  shown_at TEXT NOT NULL,
  tip_id TEXT REFERENCES tips(id) ON DELETE SET NULL,
  action_taken TEXT,
  reached_pct REAL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (action_taken IS NULL OR action_taken IN ('started', 'tiny_start', 'break_down', 'moved', 'dismissed')),
  CHECK (reached_pct IS NULL OR reached_pct BETWEEN 0 AND 100),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS tips (
  id TEXT PRIMARY KEY NOT NULL,
  text TEXT NOT NULL,
  context TEXT NOT NULL,
  tone TEXT NOT NULL DEFAULT 'calm',
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (context IN ('big', 'boring', 'tired', 'slump', 'missed_start', 'general')),
  CHECK (tone IN ('calm', 'energetic', 'tough')),
  CHECK (is_active IN (0, 1))
);

CREATE TABLE IF NOT EXISTS user_hidden_tips (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  tip_id TEXT NOT NULL REFERENCES tips(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE IF NOT EXISTS motivation_lines (
  id TEXT PRIMARY KEY NOT NULL,
  text TEXT NOT NULL,
  context TEXT NOT NULL,
  tone TEXT NOT NULL DEFAULT 'calm',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (context IN ('morning', 'behind', 'comeback', 'milestone', 'focus', 'start', 'shift')),
  CHECK (tone IN ('calm', 'energetic', 'tough'))
);

CREATE TABLE IF NOT EXISTS habits (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  icon TEXT,
  color TEXT,
  cadence TEXT NOT NULL DEFAULT 'daily',
  times_per_week INTEGER,
  target_count INTEGER NOT NULL DEFAULT 1,
  unit TEXT,
  goal_id TEXT REFERENCES goals(id) ON DELETE SET NULL,
  paused_until TEXT,
  archived_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (cadence IN ('daily', 'weekdays', 'n_per_week')),
  CHECK (times_per_week IS NULL OR times_per_week BETWEEN 1 AND 7),
  CHECK (target_count > 0),
  CHECK (paused_until IS NULL OR paused_until GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS habit_logs (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  habit_id TEXT NOT NULL REFERENCES habits(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 1,
  logged_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (count > 0)
);

CREATE TABLE IF NOT EXISTS goals (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  category_id TEXT REFERENCES categories(id) ON DELETE SET NULL,
  target_type TEXT NOT NULL,
  target_value REAL,
  due_date TEXT,
  achieved_at TEXT,
  archived_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  deleted_at TEXT,
  CHECK (target_type IN ('hours', 'tasks', 'habit_days', 'date')),
  CHECK (target_value IS NULL OR target_value > 0),
  CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS streaks (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  scope TEXT NOT NULL,
  scope_ref_id TEXT UNIQUE,
  current INTEGER NOT NULL DEFAULT 0,
  best INTEGER NOT NULL DEFAULT 0,
  freezes_left INTEGER NOT NULL DEFAULT 0,
  last_counted_date TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (scope IN ('overall', 'category', 'routine', 'habit')),
  CHECK (current >= 0),
  CHECK (current IS NULL OR best >= current),
  CHECK (freezes_left >= 0),
  CHECK (last_counted_date IS NULL OR last_counted_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS streak_freezes (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  streak_id TEXT NOT NULL REFERENCES streaks(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  consented_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')
);

CREATE TABLE IF NOT EXISTS achievement_defs (
  code TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (category IN ('consistency', 'timing', 'comeback', 'mastery', 'shifting', 'attendance', 'focus', 'habits', 'goals'))
);

CREATE TABLE IF NOT EXISTS achievements (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code TEXT NOT NULL REFERENCES achievement_defs(code),
  unlocked_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE IF NOT EXISTS reflections (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  period TEXT NOT NULL,
  period_start TEXT NOT NULL,
  text TEXT,
  rating INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (period IN ('day', 'week', 'month')),
  CHECK (period_start GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS apex_states (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  visual_theme TEXT NOT NULL DEFAULT 'mountain',
  stage INTEGER NOT NULL DEFAULT 1,
  daily_state TEXT NOT NULL DEFAULT 'normal',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (visual_theme IN ('mountain', 'tree', 'flame', 'skyline', 'constellation')),
  CHECK (stage >= 1),
  CHECK (daily_state IN ('dim', 'normal', 'bright')),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS xp_events (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  source TEXT NOT NULL,
  source_id TEXT,
  xp INTEGER NOT NULL,
  undone_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (source IN ('task', 'partial', 'top3_bonus', 'quest', 'ritual', 'achievement'))
);

CREATE TABLE IF NOT EXISTS quest_defs (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  text TEXT NOT NULL,
  xp INTEGER NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (xp > 0),
  CHECK (is_active IN (0, 1))
);

CREATE TABLE IF NOT EXISTS user_quests (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  quest_id TEXT NOT NULL REFERENCES quest_defs(id),
  completed_at TEXT,
  xp_awarded INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (xp_awarded >= 0),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS seasonal_events (
  id TEXT PRIMARY KEY NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (start_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (start_date IS NULL OR end_date >= start_date)
);

CREATE TABLE IF NOT EXISTS weekly_plans (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start TEXT NOT NULL,
  step INTEGER NOT NULL DEFAULT 1,
  goal_text TEXT,
  headline TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (week_start GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (step BETWEEN 1 AND 3),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS conflict_log (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  entity_table TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  field TEXT NOT NULL,
  kept_value_json TEXT,
  discarded_value_json TEXT,
  kept_device_id TEXT REFERENCES devices(id) ON DELETE SET NULL,
  discarded_device_id TEXT REFERENCES devices(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (kept_value_json IS NULL OR json_valid(kept_value_json)),
  CHECK (discarded_value_json IS NULL OR json_valid(discarded_value_json))
);

CREATE TABLE IF NOT EXISTS history_log (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  entity_table TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  date TEXT,
  action TEXT NOT NULL,
  before_json TEXT,
  after_json TEXT,
  reason TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (date IS NULL OR date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (before_json IS NULL OR json_valid(before_json)),
  CHECK (after_json IS NULL OR json_valid(after_json))
);

CREATE TABLE IF NOT EXISTS notification_log (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  channel TEXT NOT NULL,
  kind TEXT NOT NULL,
  task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL,
  group_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (channel IN ('in_tab', 'push', 'email'))
);

CREATE TABLE IF NOT EXISTS email_preferences (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 0,
  unsubscribe_token_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  CHECK (kind IN ('daily_plan', 'weekly_review', 'streak_at_risk', 'yearly_export')),
  CHECK (enabled IN (0, 1)),
  CHECK (json_valid(field_versions_json))
);

CREATE TABLE IF NOT EXISTS daily_totals (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date TEXT NOT NULL,
  planned_count INTEGER NOT NULL DEFAULT 0,
  done_count INTEGER NOT NULL DEFAULT 0,
  credit_sum REAL NOT NULL DEFAULT 0,
  completion_pct REAL NOT NULL DEFAULT 0,
  planned_min INTEGER NOT NULL DEFAULT 0,
  focus_min INTEGER NOT NULL DEFAULT 0,
  top3_planned INTEGER NOT NULL DEFAULT 0,
  top3_done INTEGER NOT NULL DEFAULT 0,
  xp INTEGER NOT NULL DEFAULT 0,
  streak_counted INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  field_versions_json TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (user_id, date),
  CHECK (date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (planned_count >= 0),
  CHECK (done_count >= 0),
  CHECK (credit_sum >= 0),
  CHECK (completion_pct BETWEEN 0 AND 100),
  CHECK (planned_min >= 0),
  CHECK (focus_min >= 0),
  CHECK (top3_planned BETWEEN 0 AND 3),
  CHECK (top3_done BETWEEN 0 AND 3),
  CHECK (xp >= 0),
  CHECK (streak_counted IN (0, 1)),
  CHECK (json_valid(field_versions_json))
);

CREATE INDEX IF NOT EXISTS idx_auth_identities_user_id ON auth_identities (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_auth_identities_provider_provider_subject ON auth_identities (provider, provider_subject);
CREATE INDEX IF NOT EXISTS idx_login_tokens_user_id ON login_tokens (user_id);
CREATE INDEX IF NOT EXISTS idx_devices_user_id ON devices (user_id);
CREATE INDEX IF NOT EXISTS idx_categories_user_id ON categories (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_categories_user_id_name ON categories (user_id, name) WHERE deleted_at is null;
CREATE INDEX IF NOT EXISTS idx_categories_deleted_at ON categories (deleted_at);
CREATE INDEX IF NOT EXISTS idx_tags_user_id ON tags (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tags_user_id_name ON tags (user_id, name) WHERE deleted_at is null;
CREATE INDEX IF NOT EXISTS idx_tags_deleted_at ON tags (deleted_at);
CREATE INDEX IF NOT EXISTS idx_task_tags_tag_id ON task_tags (tag_id);
CREATE INDEX IF NOT EXISTS idx_task_tags_deleted_at ON task_tags (deleted_at);
CREATE INDEX IF NOT EXISTS idx_routines_user_id ON routines (user_id);
CREATE INDEX IF NOT EXISTS idx_routines_user_id_active_from ON routines (user_id, active_from);
CREATE INDEX IF NOT EXISTS idx_routines_deleted_at ON routines (deleted_at);
CREATE INDEX IF NOT EXISTS idx_routine_tasks_routine_id ON routine_tasks (routine_id);
CREATE INDEX IF NOT EXISTS idx_routine_tasks_deleted_at ON routine_tasks (deleted_at);
CREATE INDEX IF NOT EXISTS idx_routine_pauses_routine_id ON routine_pauses (routine_id);
CREATE INDEX IF NOT EXISTS idx_routine_pauses_deleted_at ON routine_pauses (deleted_at);
CREATE INDEX IF NOT EXISTS idx_tasks_user_id ON tasks (user_id);
CREATE VIRTUAL TABLE IF NOT EXISTS tasks_fts USING fts5(title, notes, content='tasks', content_rowid='rowid');
CREATE TRIGGER IF NOT EXISTS tasks_ai AFTER INSERT ON tasks BEGIN INSERT INTO tasks_fts(rowid, title, notes) VALUES (new.rowid, new.title, new.notes); END;
CREATE TRIGGER IF NOT EXISTS tasks_ad AFTER DELETE ON tasks BEGIN INSERT INTO tasks_fts(tasks_fts, rowid, title, notes) VALUES ('delete', old.rowid, old.title, old.notes); END;
CREATE TRIGGER IF NOT EXISTS tasks_au AFTER UPDATE ON tasks BEGIN INSERT INTO tasks_fts(tasks_fts, rowid, title, notes) VALUES ('delete', old.rowid, old.title, old.notes); INSERT INTO tasks_fts(rowid, title, notes) VALUES (new.rowid, new.title, new.notes); END;
CREATE INDEX IF NOT EXISTS idx_tasks_user_id_date_start_time ON tasks (user_id, date, start_time);
CREATE INDEX IF NOT EXISTS idx_tasks_user_id_date_p ON tasks (user_id, date) WHERE is_top3=1;
CREATE INDEX IF NOT EXISTS idx_tasks_goal_id ON tasks (goal_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tasks_routine_task_id_date ON tasks (routine_task_id, date) WHERE deleted_at is null and routine_task_id is not null;
CREATE INDEX IF NOT EXISTS idx_tasks_user_id_status ON tasks (user_id, status);
CREATE INDEX IF NOT EXISTS idx_tasks_deleted_at ON tasks (deleted_at);
CREATE INDEX IF NOT EXISTS idx_subtasks_task_id ON subtasks (task_id);
CREATE INDEX IF NOT EXISTS idx_subtasks_deleted_at ON subtasks (deleted_at);
CREATE INDEX IF NOT EXISTS idx_task_links_task_id ON task_links (task_id);
CREATE INDEX IF NOT EXISTS idx_task_links_deleted_at ON task_links (deleted_at);
CREATE INDEX IF NOT EXISTS idx_task_templates_user_id ON task_templates (user_id);
CREATE INDEX IF NOT EXISTS idx_task_templates_deleted_at ON task_templates (deleted_at);
CREATE INDEX IF NOT EXISTS idx_template_subtasks_template_id ON template_subtasks (template_id);
CREATE INDEX IF NOT EXISTS idx_template_subtasks_deleted_at ON template_subtasks (deleted_at);
CREATE INDEX IF NOT EXISTS idx_inbox_items_user_id ON inbox_items (user_id);
CREATE INDEX IF NOT EXISTS idx_inbox_items_user_id_archived_at ON inbox_items (user_id, archived_at);
CREATE INDEX IF NOT EXISTS idx_inbox_items_deleted_at ON inbox_items (deleted_at);
CREATE INDEX IF NOT EXISTS idx_day_plans_user_id ON day_plans (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_day_plans_user_id_date ON day_plans (user_id, date);
CREATE INDEX IF NOT EXISTS idx_shift_batches_user_id ON shift_batches (user_id);
CREATE INDEX IF NOT EXISTS idx_shift_batches_user_id_from_date ON shift_batches (user_id, from_date);
CREATE INDEX IF NOT EXISTS idx_overrides_user_id ON overrides (user_id);
CREATE INDEX IF NOT EXISTS idx_overrides_user_id_date ON overrides (user_id, date);
CREATE INDEX IF NOT EXISTS idx_overrides_batch_id ON overrides (batch_id);
CREATE INDEX IF NOT EXISTS idx_timetables_user_id ON timetables (user_id);
CREATE INDEX IF NOT EXISTS idx_timetables_deleted_at ON timetables (deleted_at);
